// Optional <DD> description. Because <DT> is typically left unclosed in
// this format, the <DD> may parse as a sibling of the <DT> or as a nested
// child. Check both placements.
let description = null;
const dt = a.closest('dt');
if (dt) {
  let dd = null;
  if (dt.nextElementSibling && dt.nextElementSibling.tagName === 'DD') {
    dd = dt.nextElementSibling;
  } else {
    dd = dt.querySelector('dd');
  }
  if (dd) {
    // Use only the DD's own text, excluding any nested anchors.
    const text = dd.childNodes
      .filter((n) => n.nodeType === 3 /* text */)
      .map((n) => n.rawText)
      .join('')
      .trim();
    description = text || dd.text.trim() || null;
  }
}

