input.content:
:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --border: #d9dde3;
  --text: #1f2430;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
  --radius: 10px;
  --fs: 15px;
}
html[data-text-size='small'] { --fs: 13px; }
html[data-text-size='medium'] { --fs: 15px; }
html[data-text-size='large'] { --fs: 18px; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: var(--fs);
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 18px;
  background: var(--card);
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand { font-weight: 700; font-size: 1.15em; }
.quick-add { display: flex; gap: 6px; flex: 1; min-width: 240px; }
.quick-add input { flex: 1; }
.views { display: flex; gap: 4px; }
.view-tab {
  background: transparent;
  border: 1px solid transparent;
  padding: 6px 12px;
  border-radius: var(--radius);
  cursor: pointer;
  color: var(--muted);
}
.view-tab.active { background: var(--accent); color: #fff; }

input, textarea, select, button {
  font-size: 1em;
  font-family: inherit;
}
input[type='text'], input[type='number'], textarea, select {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}
button {
  padding: 8px 14px;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #fff;
  border-radius: 8px;
  cursor: pointer;
}
button.ghost { background: #fff; color: var(--accent); }
button.danger { background: var(--danger); border-color: var(--danger); }
button.primary { font-weight: 600; }

.app { max-width: 900px; margin: 0 auto; padding: 18px; }

.controls { display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }
.search-form { display: flex; gap: 6px; }
.search-form input { flex: 1; }
.controls-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.controls-row label { display: flex; gap: 6px; align-items: center; color: var(--muted); }
.saved-searches { display: flex; gap: 6px; align-items: center; }
.search-error {
  color: var(--danger);
  background: #fef2f2;
  border: 1px solid #fecaca;
  padding: 8px 10px;
  border-radius: 8px;
}

.bulk-bar {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  padding: 10px;
  border-radius: var(--radius);
  margin-bottom: 12px;
}
.bulk-bar input[type='text'] { width: 160px; }
.apply-all { display: flex; gap: 6px; align-items: center; color: var(--muted); font-size: .9em; }

.list { display: flex; flex-direction: column; gap: 10px; }
.card {
  display: flex;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px;
  align-items: flex-start;
}
.card.unread { border-left: 4px solid var(--accent); }
.card-select { margin-top: 3px; }
.card-icon { width: 20px; height: 20px; flex-shrink: 0; margin-top: 2px; border-radius: 4px; background: #eee; object-fit: cover; }
.card-body { flex: 1; min-width: 0; }
.card-title {
  font-weight: 600;
  margin: 0 0 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.card-title a { color: var(--text); text-decoration: none; }
.card-title a:hover { color: var(--accent); text-decoration: underline; }
.card-desc {
  color: var(--muted);
  margin: 0 0 6px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card-url { font-size: .82em; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-tags { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 6px; }
.tag {
  background: #eef2ff;
  color: #3730a3;
  border-radius: 999px;
  padding: 2px 9px;
  font-size: .8em;
  cursor: pointer;
  border: none;
}
.card-actions { display: flex; flex-direction: column; gap: 4px; }
.card-actions button { padding: 4px 8px; font-size: .82em; background: #fff; color: var(--accent); border-color: var(--border); }

.badge { font-size: .72em; padding: 1px 6px; border-radius: 6px; background: #f1f5f9; color: var(--muted); margin-left: 6px; }

.empty-state, .pager { text-align: center; color: var(--muted); padding: 40px 10px; }
.pager { padding: 16px; display: flex; gap: 12px; justify-content: center; align-items: center; }

.preferences-region { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; display: flex; flex-direction: column; gap: 14px; max-width: 360px; }
.preferences-region label { display: flex; flex-direction: column; gap: 5px; }
.pref-status { color: #16a34a; }

dialog#editor {
  border: none;
  border-radius: 14px;
  padding: 22px;
  width: min(620px, 92vw);
  box-shadow: 0 20px 60px rgba(0,0,0,.25);
}
dialog::backdrop { background: rgba(0,0,0,.4); }
#editor-form { display: flex; flex-direction: column; gap: 10px; }
#editor-form label { display: flex; flex-direction: column; gap: 4px; font-size: .9em; color: var(--muted); }
#editor-form label.checkbox { flex-direction: row; align-items: center; gap: 8px; color: var(--text); }
.editor-preview img { max-height: 140px; border-radius: 8px; border: 1px solid var(--border); }
.note-toolbar { display: flex; gap: 4px; }
.note-toolbar button { padding: 4px 10px; background: #fff; color: var(--text); border-color: var(--border); }
.note-editor {
  min-height: 90px;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px;
  background: #fff;
}
.note-editor:focus { outline: 2px solid var(--accent); }
.tag-suggestions { display: flex; gap: 5px; flex-wrap: wrap; }
.tag-suggestions .tag:hover { background: #dbeafe; }
.editor-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 6px; }
.editor-actions .spacer { flex: 1; }
.editor-status { color: var(--muted); min-height: 1.2em; }

.toast {
  position: fixed;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  background: #111827;
  color: #fff;
  padding: 12px 18px;
  border-radius: 10px;
  box-shadow: 0 8px 30px rgba(0,0,0,.3);
  z-index: 100;
  max-width: 90vw;
}
.toast.error { background: var(--danger); }

